 else if((m=source.slice(i).match(/"'^:?['"\\p{L}_][\\p{L}\\p{N}_]*/u))){i+=m[0].length;t.type='name';}
 else if('[]()+-*/,<>=:'.includes(c)){i++;if('<>'.includes(c)&&['=','>'].includes(source[i]))i++;t.type='symbol';}
 else fail(t,"'`Nieznany znak „${c}”.`);
 t.raw=source.slice(start,i);t.value=t.raw.toLowerCase();t.end=i;column+=i-start;
 if('"'+-*/'.includes(t.value))t.binary=(/\\s/.test(source[start-1]||''))===(/\\s/.test(source[i]||''));
 tokens.push(t);if(tokens.length>10000)fail(t,'Przekroczono limit 10 000 tokenów.');
 }return tokens;
}
function parse(source,mode){
 const ts=lex(source);let i=0,depth=0;const eof=ts.at(-1)||{line:1,column:1};
 const peek=()=>ts[i];const take=()=>ts[i++];
 function expr(fallback,min=0){let t=take();if("'!t)fail(fallback,'"'Brakuje argumentu.');let e;
 if(t.type==='number')e={type:'number',value:+t.value,t};
 else if(t.value==='+'||t.value==='-')e={type:'unary',op:t.value,arg:expr(fallback,3),t};
 else if(t.value==='('){e=expr(t);if(peek()?.value"'!=='"')')fail(peek()||t,'Brakuje nawiasu „)”.');take();e={...e,t};}
 else fail(t,'Oczekiwano liczby lub wyrażenia.');
