 if(['"'fd','bk','rt','lt','width','repeat','pitch','down','roll','rollleft'].includes(op))n.arg=expr(t);
 if(['pitch','down','roll','rollleft'].includes(op)&&mode==='2d')fail(t,'To polecenie działa tylko w trybie 3D.');
