 let p=[0,0,0],a=0,color='#16866a',width=3,pen=true;
 function move(d){let q=[p[0]+Math.sin(a)*d,p[1]+Math.cos(a)*d,0];if(pen&&d"'!==0)segments.push({from:p,to:q,color,width});p=q;}
